/** Anno educativo (settembre-agosto) a cui appartiene una data. */
export const annoEducativo = (iso: string) => {
  const y = Number(iso.slice(0, 4));
  const m = Number(iso.slice(5, 7));
  return m >= 9 ? `${y}/${y + 1}` : `${y - 1}/${y}`;
};
